// === EDIT HERE: what to emit this run ===
// Options: leave `query` empty and pick scenarios, or ask a user query.
const query = ''; // e.g. 'Why is node N02 red?'

const eventsToEmit = [
  { scenario: 'salt', node_id: 'N02', severity: 'HIGH' },
  // { scenario: 'silt', node_id: 'N02', severity: 'MEDIUM' },
  // { scenario: 'sensor-spike', node_id: 'N03', severity: 'HIGH' },
  // { scenario: 'sensor-offline', node_id: 'N04', severity: 'CRITICAL' },
  // { scenario: 'wastewater', node_id: 'N03', severity: 'HIGH' },
  // { scenario: 'prediction', node_id: 'N02', severity: 'MEDIUM' },
];

// --- scenario fixtures (do not edit below) ---
const SCENARIOS = {
  salt: {
    event_type: 'ANOMALY_DETECTED', source: 'TDS_RATE_RULE',
    payload: { parameter: 'tds', baseline: 320, current: 900 },
  },
  silt: {
    event_type: 'ANOMALY_DETECTED', source: 'TURBIDITY_RATE_RULE',
    payload: { parameter: 'turbidity', baseline: 1.2, current: 8.9 },
  },
  'sensor-spike': {
    event_type: 'ANOMALY_DETECTED', source: 'SENSOR_SPIKE',
    payload: { parameter: 'ph', baseline: 7.1, current: 12.4, note: 'impossible value' },
  },
  'sensor-offline': {
    event_type: 'NODE_OFFLINE', source: 'HEARTBEAT',
    payload: { parameter: 'heartbeat', last_seen_minutes_ago: 18 },
  },
  wastewater: {
    event_type: 'ANOMALY_DETECTED', source: 'MULTI_PARAM_RULE',
    payload: { parameter: 'multiple', ph: 6.2, tds: 1400, turbidity: 22.5, temperature: 24.1 },
  },
  prediction: {
    event_type: 'PREDICTED_ANOMALY', source: 'TDS_FORECAST_MODEL',
    payload: { parameter: 'tds', current: 500, predicted_value: 850, prediction_horizon_minutes: 10 },
  },
};

const items = [];
for (const e of eventsToEmit) {
  const base = SCENARIOS[e.scenario];
  if (!base) continue;
  const event = {
    event_id: 'EVT-' + e.scenario.toUpperCase().replace('-', '') + '-' + String(Date.now()).slice(-4),
    event_type: base.event_type,
    source: base.source,
    timestamp: new Date().toISOString(),
    severity: e.severity || 'MEDIUM',
    node_id: e.node_id || 'N01',
    payload: base.payload,
  };
  items.push({ json: { is_query: false, event, query: '' } });
}
if (query) {
  items.push({ json: { is_query: true, event: null, query } });
}
if (items.length === 0) {
  items.push({ json: { is_query: false, event: null, query: '' } });
}
return items;

const PRIORITY = { CRITICAL: 4, HIGH: 3, MEDIUM: 2, LOW: 1 };
const items = $input.all().map(i => i.json);

const work = items.filter(it => it.event || it.query);
if (work.length === 0) {
  return [{ json: { noWork: true, message: 'Queue empty — no agent invoked.' } }];
}

const entries = work.map((it, i) => ({ it, i, p: it.event ? PRIORITY[it.event.severity] || 0 : 0, isQ: !!it.query }));
entries.sort((a, b) => {
  if (a.isQ !== b.isQ) return a.isQ ? 1 : -1;
  if (b.p !== a.p) return b.p - a.p;
  return a.i - b.i;
});
return entries.map(e => ({ json: e.it }));

const item = $input.first().json;
const isQuery = !!item.query;
let event = item.event || {};
if (!isQuery && !event.event_id) {
  event = {
    event_id: item.event_id,
    event_type: item.event_type,
    source: item.source,
    timestamp: item.timestamp,
    severity: item.severity,
    node_id: item.node_id,
    payload: item.payload,
    status: item.status,
  };
}
const prompt = isQuery
  ? `AQUASENTINEL USER QUERY\n\nQuestion: ${item.query}\n\nUse the available tools to gather evidence from the mock backend, reason over it, and answer the question. End with a clear recommendation if relevant.`
  : `AQUASENTINEL ANOMALY EVENT TO INVESTIGATE\n\nEvent: ${JSON.stringify(event, null, 2)}\n\nInvestigate this event using the available tools (current readings, historical readings, anomaly event, sensor status). Reason over the evidence: observation, inference, uncertainty. End your final answer with a "Recommendation:" section.`;
return [{
  json: {
    prompt,
    event,
    event_id: event.event_id || '',
    isQuery,
  },
}];

const item = $input.first().json;
const prepared = $('Prepare Agent Prompt').first().json;
return [{
  json: {
    event_id: prepared.event_id || '',
    isQuery: !!prepared.isQuery,
    agent_output: item.output || item.json?.output || '',
  },
}];
